const body = $json.body ?? $json;
const platform = String(body.platform || '').trim().toLowerCase();
const action = String(body.action ?? '').trim().toLowerCase();
// Keep this intake contract aligned with the executor actually deployed today.
// Provider names in the registry do not imply that an action adapter exists.
if (platform !== 'telegram' || action !== 'send_message') {
  throw new Error('unsupported_action:only_telegram_send_message_is_enabled');
}
const connectionId = String(body.connection_id ?? '').trim();
if (!connectionId) throw new Error('connection_id_required');
const targetId = String(body.target_id ?? body.payload?.chat_id ?? '').trim();
if (!targetId) throw new Error('target_chat_required');
const payload = body.payload ?? {};
if (typeof payload !== 'object' || Array.isArray(payload) || payload === null) {
  throw new Error('payload_must_be_object');
}
const message = String(payload.text ?? payload.message ?? '').trim();
if (!message) throw new Error('message_text_required');
if (message.length > 4096) throw new Error('message_too_long');
const requestedKey = String(body.idempotency_key ?? '').trim();
if (requestedKey && (requestedKey.length > 200 || !/^[A-Za-z0-9._:-]+$/.test(requestedKey))) {
  throw new Error('invalid_idempotency_key');
}
const idempotencyKey = requestedKey || ('n8n-' + $execution.id);
return [{json:{
  platform,
  action,
  connection_id:connectionId,
  client_id:body.client_id ?? null,
  target_type:body.target_type ?? 'chat',
  target_id:targetId,
  idempotency_key:idempotencyKey,
  payload:{text:message}
}}];
